import numpy as np
from cad_env import CADModel, DesignProblem, FEASolver, inspect_design
import json
import copy

problem = DesignProblem.load_json("/app/problem.json")

def load_from_json(path):
    with open(path, "r") as f:
        design = json.load(f)
    actions = []
    for act in design["actions"]:
        params = act["params"]
        if act["action_type"] == "polygon":
            pts = [(params[0], params[1]), (params[2], params[3]), (params[4], params[5])]
            fillet = params[6]
            actions.append({"type": "poly", "points": pts, "fillet": fillet})
        elif act["action_type"] == "circle":
            actions.append({"type": "circle", "x": params[0], "y": params[1], "r": params[2]})
    return actions

best_actions = load_from_json("/app/design.json")

def make_model(actions):
    model = CADModel(problem)
    for act in actions:
        if act["type"] == "poly":
            model.cut_polygon(act["points"], act["fillet"])
        elif act["type"] == "circle":
            model.cut_circle(act["x"], act["y"], act["r"])
    return model

best_model = make_model(best_actions)
best_report = inspect_design(problem, best_model)
best_comp = best_report['total_compliance']

print(f"Start: Vol: {best_report['volume_fraction']:.4f}, Comp: {best_comp:.2f}, Stress: {best_report['max_von_mises_stress']:.2f}")

for i in range(2000):
    new_actions = copy.deepcopy(best_actions)

    act_idx = np.random.randint(len(new_actions))

    if new_actions[act_idx]["type"] == "poly":
        pt_idx = np.random.randint(len(new_actions[act_idx]["points"]))
        dx = np.random.normal(0, 0.3)
        dy = np.random.normal(0, 0.3)
        if act_idx == 0:
            if pt_idx == 1:
                continue
            if pt_idx == 0:
                new_actions[act_idx]["points"][pt_idx] = (new_actions[act_idx]["points"][pt_idx][0] + dx, 30.0)
            elif pt_idx == 2:
                new_actions[act_idx]["points"][pt_idx] = (60.0, new_actions[act_idx]["points"][pt_idx][1] + dy)
        else:
            if pt_idx == 1: 
                new_actions[act_idx]["points"][pt_idx] = (new_actions[act_idx]["points"][pt_idx][0] + dx, 6.0)
            else: 
                if pt_idx == 0:
                    new_actions[act_idx]["points"][pt_idx] = (new_actions[act_idx]["points"][pt_idx][0] + dx, new_actions[act_idx]["points"][pt_idx][1] + dy)
                    new_actions[act_idx]["points"][2] = (new_actions[act_idx]["points"][pt_idx][0], new_actions[act_idx]["points"][2][1])
                elif pt_idx == 2:
                    new_actions[act_idx]["points"][pt_idx] = (new_actions[act_idx]["points"][pt_idx][0] + dx, new_actions[act_idx]["points"][pt_idx][1] + dy)
                    new_actions[act_idx]["points"][0] = (new_actions[act_idx]["points"][pt_idx][0], new_actions[act_idx]["points"][0][1])
    else:
        new_actions[act_idx]["x"] += np.random.normal(0, 0.5)
        new_actions[act_idx]["y"] += np.random.normal(0, 0.5)

    new_model = make_model(new_actions)

    try:
        report = inspect_design(problem, new_model)
        vol = report['volume_fraction']
        comp = report['total_compliance']
        stress = report['max_von_mises_stress']
        valid = report['structurally_connected'] and report['wall_thickness_ok'] and len(report['feature_violations']) == 0

        if valid and vol <= 0.450 and stress <= 1.35:
            if comp < best_comp:
                best_comp = comp
                best_report = report
                best_actions = new_actions
                print(f"[{i}] New Best! Vol: {vol:.4f}, Comp: {comp:.2f}, Stress: {stress:.2f}")
                new_model.save_json("/app/design.json")
    except Exception as e:
        pass

print("Finished fine-tuning.")
